insert into public.homepage_sections ("key", "label", "content", "status", "position", "updated_at", "updated_by") values ('about'::text, 'About'::text, '{"body": "At Timeless Ties Events & Decor, we believe every celebration deserves a setting as special as the people in it. With a passion for creativity and an eye for detail, we design spaces that bring your vision to life — beautifully, effortlessly, and with a personal touch.", "image": {"alt": "Long dining table styled with flowers, candles and glassware", "src": "/images/event-table-styling.jpg", "width": 1600, "height": 1067, "mediaId": "c4938e8f-52e6-4a0c-92ef-aa46aba49173"}, "eyebrow": "About Us", "heading": "Your Vision. Our Craft.", "features": [{"icon": "design", "text": "Tailored to your style", "title": "Bespoke Décor"}, {"icon": "details", "text": "Little things, big impact", "title": "Thoughtful Details"}, {"icon": "execution", "text": "From setup to send-off", "title": "Seamless Execution"}]}'::jsonb, 'PUBLISHED'::content_status, '1'::integer, '2026-10-08 23:29:20.78123+09'::timestamp with time zone, null) on conflict do nothing;
