insert into public.site_settings ("key", "value", "is_public", "updated_at", "updated_by") values ('about'::text, '{"image": {"alt": "Couple in traditional red wedding attire standing before a carved archway framed with roses", "src": "/images/couple-floral-archway.jpg", "focus": "50% 40%", "width": 1600, "height": 1244, "mediaId": "c2820053-d54a-487b-93cc-16d08cb388c6"}, "title": "About Us", "eyebrow": "Our studio", "heading": "Celebrations, designed with care.", "ctaImage": {"alt": "Couple seated for a wedding ritual under a white floral mandap in a candle-lit ballroom", "src": "/images/mandap-ceremony-ballroom.jpg", "width": 1600, "height": 1067, "mediaId": "17c8e3e8-7742-42b8-9e0e-ad6740bd88e7"}, "subtitle": "Wedding décor · Event styling · Celebrations", "paragraphs": ["Timeless Ties Events & Decor is a Kathmandu-based décor studio. From intimate family functions to full wedding celebrations, we design and build the setting so you can focus on the people who matter.", "Every event starts with your ideas, your traditions and your budget. We turn them into a setup that feels personal — and we take care of it from the first sketch to the final finishing touch."]}'::jsonb, 'true'::boolean, '2026-10-08 23:29:20.793011+09'::timestamp with time zone, null) on conflict do nothing;
insert into public.site_settings ("key", "value", "is_public", "updated_at", "updated_by") values ('business'::text, '{"geo": {"lat": 27.7172, "lng": 85.3461}, "logo": {"alt": "Timeless Ties Events & Decor", "src": "/brand/logo-wine.png", "width": 311, "height": 287, "mediaId": "88a41256-a51c-4b9f-aaba-e2ff4b9fafd6"}, "name": "Timeless Ties Events & Decor", "email": "timelesstieseventsdecor@gmail.com", "title": "Timeless Ties Events & Decor | Wedding & Event Decoration in Kathmandu", "locale": "en_NP", "phones": [{"e164": "+9779845411029", "label": "984-5411029"}, {"e164": "+9779821896505", "label": "982-1896505"}], "address": {"city": "Kathmandu", "region": "Bagmati", "street": "Chabahil", "country": "Nepal", "postalCode": "44600", "countryCode": "NP"}, "tagline": "Weddings · Events · Celebrations", "currency": "NPR", "timezone": "Asia/Kathmandu", "whatsapp": "9779845411029", "shortName": "Timeless Ties", "areaServed": ["Kathmandu", "Lalitpur", "Bhaktapur"], "logoOnDark": {"alt": "Timeless Ties Events & Decor", "src": "/brand/logo-ivory.png", "width": 311, "height": 287, "mediaId": "0051349d-e587-49df-b53e-0209d9b6dc3d"}, "description": "Timeless Ties Events & Decor creates elegant wedding and event décor in Kathmandu, Nepal. Explore our work and plan your celebration with us.", "announcement": "Creating unforgettable moments across Kathmandu", "whatsappMessage": "Hi Timeless Ties! I''d like to ask about décor for my event."}'::jsonb, 'true'::boolean, '2026-10-08 23:29:20.773903+09'::timestamp with time zone, null) on conflict do nothing;
insert into public.site_settings ("key", "value", "is_public", "updated_at", "updated_by") values ('catalogue_meta'::text, '{"offerings": ["Event Management & Coordination", "Floral Decoration", "Wedding Concept & Décor", "Venues & Locations", "Band Baja & Panche Baja", "Live Nepali Instrumental & Live Band", "Bridal Styling — Makeup & Hair", "Lighting & Tent Setup", "Horse Cart", "Choreographer & Emcee", "Mehendi Artist & Live Painting", "DJ & Sound System", "Photography & Videography", "Saipata & Supadi Packaging", "Dhol & Safa", "Cakes", "Shuttle Service & Vehicle Hire"], "priceNote": "Prices are subject to change based on time and location."}'::jsonb, 'true'::boolean, '2026-10-08 23:29:20.794605+09'::timestamp with time zone, null) on conflict do nothing;
insert into public.site_settings ("key", "value", "is_public", "updated_at", "updated_by") values ('faqs'::text, '[{"a": "For weddings during the season, reaching out one to two months ahead gives the most flexibility. Smaller functions can often be arranged sooner — send us your date and we''ll check.", "q": "How early should we book?"}, {"a": "We mostly work across the Kathmandu Valley — Kathmandu, Lalitpur and Bhaktapur. For events further away, get in touch and we''ll let you know what''s possible.", "q": "Do you work outside Kathmandu?"}, {"a": "Share your budget up front and we''ll suggest a design that fits it, with an itemised quote so you know exactly what''s included.", "q": "Can you work within our budget?"}, {"a": "Not yet. Sending an inquiry starts the conversation. We''ll contact you, discuss details and send a quote — your date is confirmed once you accept it.", "q": "Is my date confirmed once I send the form?"}]'::jsonb, 'true'::boolean, '2026-10-08 23:29:20.793808+09'::timestamp with time zone, null) on conflict do nothing;
