insert into public.site_settings ("key", "value", "is_public", "updated_at", "updated_by") values ('quotation_settings'::text, '{"terms": "1. A deposit is required to confirm the booking; the date is held only once the deposit is received.\n2. The remaining balance is due on or before the event date unless agreed otherwise in writing.\n3. Prices include setup and dismantling within Kathmandu Valley. Venues outside the valley may incur transport charges.\n4. Fresh flowers are seasonal; similar varieties may be substituted while keeping the agreed look and colours.\n5. Changes to the design after confirmation may change the price and will be quoted separately.\n6. Cancellations within 14 days of the event forfeit the deposit.\n7. The client is responsible for damage to rented décor caused by guests or the venue.", "taxRate": 0, "termsVersion": "2026-10", "validityDays": 14, "depositPercent": 50}'::jsonb, 'false'::boolean, '2026-10-08 23:29:20.7971+09'::timestamp with time zone, null) on conflict do nothing;
